% This is an autogenerated sample test for file dopplerFrequencySearch.m
classdef testdopplerFrequencySearch < matlab.unittest.TestCase

    methods (Test)

        function test_dopplerFrequencySearch_SNR100(testCase)
            SNR = 100; % Barely any noise
            testCase.runDopplerTest(SNR);
        end

        function test_dopplerFrequencySearch_SNR10(testCase)
            SNR = 10; % Some noise
            testCase.runDopplerTest(SNR);
        end

    end

    methods (Access = private)

        function runDopplerTest(testCase, SNR)

            % Specify inputs
            tCoh = 10;
            timeSignal = 10;
            Fs = 5e8;
            Fsym = 2.304e8;
            fDoppler = 3200;
            fDrange = 1600:200:4600;

            r = signalGenerator(Fs, timeSignal, fDoppler, SNR);

            signalData = struct( ...
                'SamplingFreq', Fs, ...
                'SymbolFreq', Fsym );

            % Run function
            [result, tArray] = dopplerFrequencySearch(r, signalData, tCoh, fDrange);

            [T, F] = meshgrid(tArray, fDrange);

            % Find maximum correlation
            [~, idx] = max(result(:));
            [row, col] = ind2sub(size(result), idx);
            fMax = F(row, col)

            surf(T, F, result, 'EdgeColor','none');
            xlabel('Time'); ylabel('Frequency'); zlabel('Correlation');
            view(3); colorbar; shading interp;

            figure
            plot(fDrange, result(:,col))
            xlabel('Frequency')
            ylabel('Correllation')

            % Verification with message
            testCase.verifyEqual( ...
                fMax, fDoppler, ...
                sprintf('Doppler estimation failed for SNR = %d', SNR) );

            % Optional explicit success message
            disp(['Test passed for SNR = ', num2str(SNR)])

        end

    end
end